<script setup lang="ts">
import QRCode from 'qrcode'
import { dateTime, nim } from '~/utils/presentation'
const route=useRoute(),{me,working,notice,api,task}=useShowUp()
const data=ref<any>(),qr=ref(''),token=ref(''),expiresAt=ref(0),confirmCancel=ref(false),copyFallback=ref('')
const attendeeLink=computed(()=>import.meta.client?`${window.location.origin}/e/${route.params.eventId}`:`/e/${route.params.eventId}`)
const { clock, refresh, refreshError } = useLiveRefresh(async()=>{data.value=me.value?.organizer?await api(`/api/host/events/${route.params.eventId}`):null})
const canActivate = computed(()=>data.value?.event.state==='OPEN' && clock.value>=data.value.event.check_in_opens_at && clock.value<data.value.event.check_in_closes_at)
async function copy(value:string,label:string){
  try { await navigator.clipboard.writeText(value); notice.value={tone:'success',title:label,message:'Copied to clipboard.'}; copyFallback.value='' }
  catch { copyFallback.value=value; notice.value={tone:'waiting',title:'Copy manually',message:'Select and copy the text below.'} }
}
async function activate(){
  try { await task('Activating venue QR',async()=>{const result=await api<any>(`/api/events/${route.params.eventId}/venue`,{method:'POST'});qr.value='';token.value=result.token;expiresAt.value=result.expiresAt;qr.value=await QRCode.toDataURL(result.token,{width:420,margin:2,color:{dark:'#10251e',light:'#fffdf7'}})}) } catch {}
}
async function close(){try {await task('Closing venue QR',()=>api(`/api/events/${route.params.eventId}/venue/close`,{method:'POST'}));qr.value='';token.value=''}catch{}}
async function cancel(){try {await task('Cancelling event',()=>api(`/api/events/${route.params.eventId}/cancel`,{method:'POST'}));confirmCancel.value=false;qr.value='';token.value='';await refresh()}catch{}}
async function open(){try {await task('Opening registration',()=>api(`/api/events/${route.params.eventId}/open`,{method:'POST'}));await refresh()}catch{}}
</script>
<template><div class="shell wide"><AppHeader host><WalletButton/></AppHeader><StatusNotice v-if="refreshError" tone="error" title="Refresh unavailable" :message="refreshError"/><EmptyState v-if="!me?.organizer || !data" title="Control room unavailable" message="Connect the organizer wallet or choose another campaign."/><main v-else><div class="page-head"><EventPolicyBadge :mode="data.event.payment_mode"/><h1>{{ data.event.title }}</h1><p>{{ dateTime(data.event.starts_at) }} · {{ nim(data.event.amount_luna) }}</p><p>{{ data.event.state }}</p></div><div class="host-stats"><div><strong>{{ data.summary.confirmed }}</strong><span>confirmed / {{ data.event.capacity }}</span></div><div><strong>{{ data.event.available_seats }}</strong><span>available seats</span></div><div><strong>{{ data.summary.checkedIn }}</strong><span>checked in</span></div><div><strong>{{ data.summary.refundsToCreate }}</strong><span>refunds on cancellation</span></div></div><StatusNotice v-if="notice" :tone="notice.tone" :title="notice.title" :message="notice.message"/><section class="panel"><h2>Share and operate</h2><button v-if="data.event.state==='DRAFT'" :disabled="!!working" @click="open">Open registration</button><p v-if="data.event.state==='DRAFT'">Opening registration freezes the event terms.</p><button class="secondary" @click="copy(attendeeLink,'Attendee link')">Copy attendee link</button><button class="secondary" @click="copy(data.event.id,'Event ID')">Copy event ID</button><label v-if="copyFallback" class="field">Text to copy<textarea readonly :value="copyFallback" @focus="($event.target as HTMLTextAreaElement).select()"/></label><button :disabled="!!working || !canActivate" @click="activate">{{ qr?'Rotate QR':'Activate check-in QR' }}</button><p v-if="!canActivate">Venue QR is available during the event's check-in window.</p><button :disabled="!!working||!qr" @click="close">Close QR</button><button class="secondary" @click="refresh">Refresh attendees</button><button class="danger" :disabled="!!working || data.event.state==='CANCELLED'" @click="confirmCancel=true">Cancel event</button></section><VenueQrPanel v-if="qr" :src="qr" :token="token" :expires-at="expiresAt"/><section class="panel"><h2>Attendees</h2><div v-if="data.attendees.length"><div v-for="person in data.attendees" :key="person.id" class="meta-row"><span class="mono">{{ person.wallet_short }}</span><strong>{{ person.payment_verified?'Payment verified':'Awaiting payment' }} · {{ person.state.replaceAll('_',' ').toLowerCase() }} · {{ person.settlement_state.replaceAll('_',' ').toLowerCase() }}</strong></div></div><p v-else>No reservations yet.</p></section></main><ConfirmDialog :open="confirmCancel" :title="`Cancel ${data?.event.title || 'event'}?`" :message="`${data?.summary.confirmed || 0} verified attendees are affected. ${data?.summary.refundsToCreate || 0} refund obligations will be created. Registration cannot be reopened.`" confirm-label="Cancel event and create refunds" @close="confirmCancel=false" @confirm="cancel"/></div></template>
